package com.deardiary.privateapp;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
/** Native navigation only. No Instagram DOM or session access. */
final class InstagramNav extends LinearLayout{
 interface Selected{void choose(String key);}
 InstagramNav(Context c,boolean dark,Selected selected){super(c);setOrientation(HORIZONTAL);setPadding(dp(7),dp(7),dp(7),dp(7));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.parseColor(dark?"#29232c":"#fff9f5"));bg.setCornerRadius(dp(24));setBackground(bg);String[] labels={"Home","My diary","Chat","Reels","Profile"};String[] keys={"home","diary","chat","reels","profile"};for(int i=0;i<5;i++){final String key=keys[i];LinearLayout item=new LinearLayout(c);item.setOrientation(VERTICAL);item.setGravity(Gravity.CENTER);item.setMinimumHeight(dp(52));item.setContentDescription(labels[i]);item.setFocusable(true);item.setClickable(true);boolean active=i==3;int color=Color.parseColor(dark?active?"#ffd9e6":"#cbb4bf":active?"#754856":"#846c74");if(active){GradientDrawable pill=new GradientDrawable();pill.setColor(Color.parseColor(dark?"#73435c":"#efd9e2"));pill.setCornerRadius(dp(17));item.setBackground(pill);}item.addView(new Icon(c,i==4?5:i,color),new LinearLayout.LayoutParams(dp(22),dp(22)));item.addView(new Label(c,labels[i],color),new LinearLayout.LayoutParams(-1,dp(19)));item.setOnClickListener(v->selected.choose(key));addView(item,new LinearLayout.LayoutParams(0,dp(52),1));}}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 static final class Label extends View{String text;int color;Label(Context c,String t,int col){super(c);text=t;color=col;}@Override protected void onDraw(Canvas c){super.onDraw(c);Paint p=new Paint(3);p.setColor(color);p.setTextSize((getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density<350?9:10)*getResources().getDisplayMetrics().scaledDensity);p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));p.setTextAlign(Paint.Align.CENTER);c.drawText(text,getWidth()/2f,(getHeight()-p.ascent()-p.descent())/2f,p);}}
 static final class Icon extends View{int type,color;Icon(Context c,int t,int col){super(c);type=t;color=col;}@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.scale(getWidth()/24f,getHeight()/24f);Paint p=new Paint(3);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.7f);p.setStrokeJoin(Paint.Join.ROUND);p.setStrokeCap(Paint.Cap.ROUND);Path x=new Path();switch(type){case 0:x.moveTo(3,10);x.lineTo(12,3);x.lineTo(21,10);x.moveTo(5,9);x.lineTo(5,21);x.lineTo(19,21);x.lineTo(19,9);x.moveTo(9,21);x.lineTo(9,14);x.lineTo(15,14);x.lineTo(15,21);break;case 1:x.moveTo(12,5);x.cubicTo(8,2,4,3,3,4);x.lineTo(3,20);x.cubicTo(6,18,9,18,12,21);x.cubicTo(15,18,18,18,21,20);x.lineTo(21,4);x.cubicTo(18,3,15,3,12,5);x.lineTo(12,21);break;case 2:canvas.drawRoundRect(3,3,21,19,7,7,p);x.moveTo(6,18);x.lineTo(3,22);x.lineTo(12,19);break;case 3:canvas.drawRoundRect(3,3,21,21,2,2,p);x.moveTo(3,9);x.lineTo(21,9);x.moveTo(8,3);x.lineTo(12,9);x.moveTo(15,3);x.lineTo(19,9);x.moveTo(10,12);x.lineTo(16,15);x.lineTo(10,18);x.close();break;case 4:canvas.drawRoundRect(3,5,21,21,2,2,p);x.moveTo(3,10);x.lineTo(21,10);x.moveTo(8,3);x.lineTo(8,7);x.moveTo(16,3);x.lineTo(16,7);break;case 5:canvas.drawCircle(12,7,4,p);x.moveTo(5,21);x.lineTo(5,18);x.cubicTo(5,11,19,11,19,18);x.lineTo(19,21);break;}canvas.drawPath(x,p);canvas.restore();}}
}
